pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialAmt, uint256 reentrantAmt, uint8 reentrantDepth) public {
        // Bound amounts to prevent overflow in calculations and keep within reasonable range
        initialAmt = bound(initialAmt, 1, 100 ether);
        reentrantAmt = bound(reentrantAmt, 1, 10 ether);
        reentrantDepth = uint8(bound(reentrantDepth, 2, 5));

        // Deploy attacker contract that reenters Put via fallback
        ReentrantCaller attacker = new ReentrantCaller(address(c), reentrantDepth);

        // Fund attacker with enough ether for the initial call plus all reentrant calls
        uint256 totalNeeded = initialAmt + reentrantAmt * reentrantDepth;
        vm.deal(address(attacker), totalNeeded);

        // Record attacker's balance before the call
        uint256 balanceBefore = address(attacker).balance;

        // Attacker initiates Put with initialAmt, which triggers reentrant calls of reentrantAmt each
        vm.prank(address(attacker));
        attacker.attack{value: initialAmt}(reentrantAmt);

        // After the call, the attacker's Acc balance should equal total ether sent (initial + all reentrant)
        // But due to missing reentrancy guard, the balance may be inflated
        uint256 accBalance = c.Acc(address(attacker));
        uint256 totalSent = initialAmt + reentrantAmt * reentrantDepth;

        // The correct version always ensures accBalance == totalSent.
        // The buggy version allows accBalance > totalSent because reentrant calls
        // each credit msg.value but the fallback receives no new Ether from outside.
        assertTrue(accBalance <= totalSent);
    }
}

contract ReentrantCaller {
    C public target;
    uint256 public depth;
    uint256 public reentrantValue;
    uint256 public counter;

    constructor(address _target, uint256 _depth) {
        target = C(_target);
        depth = _depth;
    }

    function attack(uint256 _reentrantValue) public payable {
        reentrantValue = _reentrantValue;
        counter = 0;
        target.Put{value: msg.value}(0);
    }

    fallback() external payable {
        if (counter < depth) {
            counter++;
            target.Put{value: reentrantValue}(0);
        }
    }
}

