pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amt, uint256 unlockTime, uint256 warpBy) public {
        // Bound amounts and times to avoid overflow and keep values reasonable
        amt = bound(amt, 1 ether, 1000 ether);
        unlockTime = bound(unlockTime, 0, type(uint64).max);
        warpBy = bound(warpBy, 0, 365 days);

        // Set up: fund an actor and have them Put with a specific unlockTime
        address actor = address(0x1234);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(unlockTime);

        // Warp to a timestamp that is STRICTLY before or equal to unlockTime
        // Only warp forward if unlockTime allows it, keep warpBy such that current time <= unlockTime
        uint256 currentTime = block.timestamp;
        if (currentTime <= unlockTime) {
            // Already at or before unlockTime, no need to warp
        } else {
            // Warp backwards is not allowed, so we must skip this case: we assume unlockTime >= currentTime
            // This means we discard test cases where unlockTime < currentTime because we can't warp backwards.
            // This is the only realistic admissible domain for testing "before unlock".
            vm.assume(unlockTime >= currentTime);
        }
        // Now we are at a timestamp <= unlockTime.

        // Record balance before Collect
        uint256 balBefore = address(c).balance;

        // Attempt to Collect
        bool ok;
        vm.prank(actor);
        try c.Collect(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: if ok == true (no revert), then the transfer must NOT have happened
        // i.e., balance of contract must remain unchanged
        uint256 balAfter = address(c).balance;

        assertTrue(!ok || balAfter == balBefore, "Collect succeeded before unlock time without transfer? Wait, check invariant");
    }
}

